WITH recent_departments AS (SELECT * FROM departments WHERE budget <= 1695000), summary AS (SELECT CASE WHEN location IN ('Berlin', 'Singapore') THEN 'group_a' ELSE 'other' END AS location_group, ROUND((100 * SUM(CASE WHEN location = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore FROM recent_departments GROUP BY CASE WHEN location IN ('Berlin', 'Singapore') THEN 'group_a' ELSE 'other' END) SELECT location_group, pct_singapore FROM summary WHERE pct_singapore < 60 ORDER BY location_group DESC;
